class Solution {
public:
    vector<int> replaceElements(vector<int>& arr) {
        int maxSoFar = -1;
        for (int i = (int)arr.size() - 1; i >= 0; i--) {
            int cur = arr[i];
            arr[i] = maxSoFar;
            maxSoFar = max(maxSoFar, cur);
        }
        return arr;
    }
};
